// Node nhận kết quả từ Qdrant
const items = $input.all();

if (items.length === 0 || !items[0].json.result.points.length) {
  return {
    json: {
      decision: "MANUAL_REVIEW",
      suggested_assignee: "Unassigned",
      suggested_assignee_id: null,
      confidence: 0
    }
  };
}

const points = items[0].json.result.points;
const votingMap = {};

// 1. Thống kê theo Trọng số lũy thừa (Power Scaling)
const POWER = 2; 
let totalScaledScore = 0;

points.forEach(p => {
  const owner = p.payload.metadata.owner || "Unknown";
  const ownerId = p.payload.metadata.owner_id || null; // Lấy assignee_id từ metadata
  const scaledScore = Math.pow(p.score || 0, POWER);

  if (!votingMap[owner]) {
    // Lưu thêm ownerId vào map
    votingMap[owner] = { count: 0, totalScore: 0, scaledScore: 0, assignee_id: ownerId };
  }

  votingMap[owner].count += 1;
  votingMap[owner].totalScore += p.score;
  votingMap[owner].scaledScore += scaledScore;
  totalScaledScore += scaledScore;
});

// 2. Tìm người thắng cuộc dựa trên Scaled Score
let winner = null;
let winnerId = null;
let maxScaledScore = -1;

for (const owner in votingMap) {
  if (votingMap[owner].scaledScore > maxScaledScore) {
    maxScaledScore = votingMap[owner].scaledScore;
    winner = owner;
    winnerId = votingMap[owner].assignee_id; // Lấy ID của người thắng
  }
}

// 3. Tính Confidence
let confidence = (maxScaledScore / totalScaledScore) * 100;

// Trình bày lại voting_stats để debug
const finalStats = {};
for (const owner in votingMap) {
  finalStats[owner] = {
    count: votingMap[owner].count,
    totalScore: votingMap[owner].totalScore,
    assignee_id: votingMap[owner].assignee_id
  };
}

const slackStyleTs = (Date.now() / 1000).toFixed(6);

return {
  json: {
    decision: confidence >= 60 ? "AUTO_ASSIGN" : "PENDING_APPROVAL",
    suggested_assignee: winner,
    suggested_assignee_id: winnerId, // Trả về thêm ID theo yêu cầu
    confidence: Math.round(confidence),
    ticket_info: {
        key: $('Extract APG Issues Info').first().json.metadata.key,
        link: $('Extract APG Issues Info').first().json.metadata.key_link
    },
    voting_stats: finalStats,
    timestate: slackStyleTs
  }
};

// Hàm thuật toán tự viết: Chuyển chuỗi Text thành Số nguyên dương (32-bit unsigned integer)
function generateNumericId(str) {
    let hash = 0;
    if (!str || str.length === 0) return hash;
    for (let i = 0; i < str.length; i++) {
        let char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash; // Convert to 32bit integer
    }
    return Math.abs(hash); // Trả về số nguyên dương
}

// 2. Hàm dùng chung để làm sạch nội dung (Dùng cho cả Desc và Comments)
function cleanJiraText(text) {
    if (!text) return "";
    let cleaned = text;

    // Xóa Code blocks, logs và Images
    cleaned = cleaned.replace(/\{noformat\}[\s\S]*?\{noformat\}/g, '');
    cleaned = cleaned.replace(/![^!]+!/g, '');

    // Xóa định dạng Jira (*, h1, h2...)
    cleaned = cleaned.replace(/\*/g, '');
    cleaned = cleaned.replace(/h[1-6]\.\s*/g, '');

    // Xóa dữ liệu nhạy cảm hoặc rác hệ thống
    cleaned = cleaned.replace(/^[ \t]*Credentials:.*$/gim, '');
    cleaned = cleaned.replace(/^[ \t]*Payload:.*$/gim, '');
    cleaned = cleaned.replace(/^[ \t\xA0]*(Issue report|Root cause|Fix|Impact):[ \t\xA0\r]*$/gim, '');

    // Nén khoảng trống
    return cleaned.trim().replace(/\n{2,}/g, '\n\n');
}

