    // --- 2. TẠO AI_DESC (Dành cho Embedding/RAG) ---
    let aiDesc = rawDesc;
    aiDesc = aiDesc.replace(/\{code[:\w]*\}[\s\S]*?\{code\}/g, '');
    aiDesc = aiDesc.replace(/\{noformat\}[\s\S]*?\{noformat\}/g, '');
    aiDesc = aiDesc.replace(/\{quote\}[\s\S]*?\{quote\}/g, '');
    aiDesc = aiDesc.replace(/![^!]+!/g, ''); 

    const technicalSections = ["More Details", "Credentials", "Environment", "Roster date", "JobId", "cURL"];
    technicalSections.forEach(section => {
        const reg = new RegExp(`${section}:[\\s\\S]*$`, 'i');
        aiDesc = aiDesc.replace(reg, '');
    });

    aiDesc = aiDesc.replace(/h[1-6]\.\s*/g, '');
    aiDesc = aiDesc.replace(/[\*_]/g, '');
    aiDesc = aiDesc.trim().replace(/\n{2,}/g, '\n\n');

    // --- 3. TẠO SLACK_DESC (Đã sửa lỗi Regex Invalid Group) ---
    let slackDisplayDesc = rawDesc;

    // A. Xóa ảnh và file đính kèm rác [^...]
    slackDisplayDesc = slackDisplayDesc.replace(/![^!]+!/g, ''); 
    slackDisplayDesc = slackDisplayDesc.replace(/\[\^[^\]]+\]/g, ''); 

    // B. Chuyển đổi các khối code
    slackDisplayDesc = slackDisplayDesc.replace(/\{code[:\w]*\}|\{code\}|\{noformat\}|\{quote\}/g, '\n```\n');

    // C. Xử lý tiêu đề h1-h6
    slackDisplayDesc = slackDisplayDesc.replace(/h[1-6]\.\s*(.*?)(?:\r?\n|$)/g, '*$1*\n');

    // D. Bôi đậm các Header kỹ thuật (SỬA LỖI TẠI ĐÂY)
    const slackHeaders = [
        "Environment", "Test case", "Actual result", "Expected result", 
        "More details", "JobId & Payload", "References", "Credentials", 
        "Issue report", "Root cause", "Fix", "Impact"
    ];

    slackHeaders.forEach(header => {
        // Loại bỏ (?i) bên trong chuỗi, sử dụng flag 'gi' ở tham số thứ 2
        // (?<!\*) giúp tránh bôi đậm chồng lên nội dung đã có dấu sao
        const reg = new RegExp(`(?<!\\*)${header}:`, 'gi');
        slackDisplayDesc = slackDisplayDesc.replace(reg, `*${header}:*`);
    });

    // E. Dọn dẹp khoảng trắng
    slackDisplayDesc = slackDisplayDesc.trim()
        .replace(/\n{3,}/g, '\n\n')
        .replace(/^\s*[\r\n]/gm, '');

    if (slackDisplayDesc.length > 2500) {
        slackDisplayDesc = slackDisplayDesc.substring(0, 2500) + "... (Xem thêm tại Jira)";
    }

    // --- 4. KẾT QUẢ CUỐI CÙNG ---
    return {
        json: {
            point_id: generateNumericId(issueKey), 
            apg_key: issueKey,
            metadata: metadataObj,
            vector_content: `Project: ${metadataObj.project}\nTask: ${metadataObj.task_name}\nDescription: ${aiDesc}`,
