// 1. Giải mã payload từ Slack
const payload = JSON.parse($json.body.payload);
const actionValue = payload.actions[0].value; 

// 2. Tách dữ liệu bằng dấu gạch đứng "|"
// Cấu trúc hiện tại trong value: [action|key|assignee_email|assignee_id|key_link]
const parts = actionValue.split('|');

return {
  action: parts[0],                // "approve" hoặc "decline"
  key: parts[1],                   // "APG-125"
  assignee: parts[2] || null,      // Email: "tri.vo@workforceoptimizer.com"
  assignee_id: parts[3] || null,   // ID: "62714a79e51c620070bd2a13"
  key_link: parts[4],              // URL Jira ticket
  message_ts: payload.container.message_ts // Dùng để update/xóa tin nhắn Slack
};

// Cấu hình phạm vi hàng
const start_row = 9; 
const end_row = 60;

// 1. Tạo list số nguyên từ start_row tới end_row (row_index)
let row_index = [];
for (let i = start_row; i <= end_row; i++) {
    row_index.push(i);
}

// 2. Lấy TOÀN BỘ danh sách row_number từ input
const existing_numbers = $input.all().map(item => Number(item.json.row_number));

// 3. Lọc (Delete): Chỉ giữ lại những số KHÔNG nằm trong mảng existing_numbers
let final_list = row_index.filter(num => !existing_numbers.includes(num));

// 4. SẮP XẾP GIẢM DẦN (DESC)
// (a, b) => b - a sẽ đưa số lớn lên trước
final_list.sort((a, b) => b - a);

// 5. Trả về kết quả dưới dạng mảng object để n8n có thể dùng ở bước sau
return final_list.map(num => ({
    row_to_process: num
}));
